_MSL = 2


def stem(word: str) -> str:
    if not word:
        return ""
    w = word.lower()
    exc = _EXC.get(w)
    if exc is not None:
        return exc
    w_len = len(w)
    curr = _ROOT
    best = None
    if type(curr) is dict and "" in curr:
        o = curr[""]
        if type(o) is int:
            if w_len - o >= _MSL:
                best = o
        elif w_len - o[0] >= 1 and w_len - o[0] + len(o[1]) >= _MSL:
            best = o
    idx = w_len - 1
    while idx >= 0:
        if type(curr) is not dict:
            break
        nxt = curr.get(w[idx])
        if nxt is None:
            break
        if type(nxt) is tuple and type(nxt[0]) is str:
            rem, nxt = nxt
            r_len = len(rem)
            if idx < r_len or w[idx - r_len : idx] != rem:
                break
            idx -= r_len
        idx -= 1
        curr = nxt
        o = curr.get("") if type(curr) is dict else curr
        if o is not None:
            if type(o) is int:
                if w_len - o >= _MSL:
                    best = o
            elif w_len - o[0] >= 1 and w_len - o[0] + len(o[1]) >= _MSL:
                best = o
    if best is not None and (
        (type(best) is int and best > 0)
        or (type(best) is tuple and (best[0] > 0 or len(best[1]) > 0))
    ):
        if type(best) is int:
            w = w[:-best]
        else:
            c, a = best
            w = (w[:-c] if c > 0 else w) + a
        exc_trie = _EXC.get(w)
        if exc_trie is not None:
            return exc_trie
    return w


def stem_batch(words: list[str]) -> list[str]:
    return [stem(w) for w in words]
